    guides = {}
    for color in colors:
        guides[color] = []
        for c in range(w):
            if grid[0][c] == color:
                guides[color].append(("top", c))
            if grid[h-1][c] == color:
                guides[color].append(("bottom", c))
        for r in range(h):
            if grid[r][0] == color:
                guides[color].append(("left", r))
            if grid[r][w-1] == color:
                guides[color].append(("right", r))
    guide_color = max(colors, key=lambda x: len(guides[x]))
    fill_color = next((x for x in colors if x != guide_color), guide_color)
